import{_ as i,o as t,c as e,a2 as l}from"./chunks/framework.CdjpmwdR.js";const b=JSON.parse('{"title":"图解 AI 基本概念：从机器学习到 LLM","description":"面向工程实践者梳理 AI 关键概念：应用领域、学习策略，以及深度学习与 LLM 的关系，帮助构建可执行的学习地图。","frontmatter":{"category":"node/agentic","date":"2023-12-01","title":"图解 AI 基本概念：从机器学习到 LLM","description":"面向工程实践者梳理 AI 关键概念：应用领域、学习策略，以及深度学习与 LLM 的关系，帮助构建可执行的学习地图。","tags":["node/agentic","LLM","Prompt"],"image":"https://pic4.zhimg.com/80/v2-9d6ab07d82076ddae616b30cf1618a63_1440w.webp"},"headers":[],"relativePath":"blogs/2023/202312-illustrated-ai.md","filePath":"blogs/2023/202312-illustrated-ai.md"}'),p={name:"blogs/2023/202312-illustrated-ai.md"};function r(o,a,c,s,h,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<blockquote><p>GPT 是什么？<br> 生成式 AI 是什么样的 AI？还有非生成式的吗？<br> 人工智能研究了这么多年 ChatGPT 为什么2022 年才进入公众视野？</p></blockquote><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>过去半年，AI 从行业话题迅速变成大众工具。无论你是否准备好，它都已经进入工作流。</p><p>对软件、设计、写作从业者而言，变化尤其直接。ChatGPT、Midjourney 等工具不只提高效率，也在重塑岗位分工和交付方式。</p><p>很多人开始系统学习 AI，但概念体系庞杂、术语密度很高。作为偏工程背景的开发者，我也经历过“名词都认识、关系不清楚”的阶段。于是我把核心概念重新整理成一张图，目标是先建立结构，再深入细节。</p><h2 id="ai-的应用领域" tabindex="-1">AI 的应用领域 <a class="header-anchor" href="#ai-的应用领域" aria-label="Permalink to &quot;AI 的应用领域&quot;">​</a></h2><p><img src="https://pic4.zhimg.com/80/v2-9d6ab07d82076ddae616b30cf1618a63_1440w.webp" alt=""></p><p>人工智能是一个存在已久的学科，其目标是研究使计算机能够模拟出人类的只能。而随着科技的发展（人类智力的发展），人工智能想要解决的问题也越来越多。但既然是模拟人，总逃不出 “眼、耳、嘴、大脑” 这些人用于接收和处理信息的感官系统。如果以解决的问题的角度划分，AI 可以分为几个应用领域：</p><ul><li>问题域：AI 应该能解决哪些问题 <ul><li>CV 视觉能力</li><li>NLP 语言能力</li><li>VC 听觉能力</li><li>KG 思维和推理能力</li></ul></li><li>复杂问题域：结合多种能力实现的复杂功能</li><li>自动驾驶、机器人、专家系统等</li><li>解决方案域：如何使 AI 有解决这些问题的能力</li><li>机器学习</li></ul><h2 id="机器学习策略" tabindex="-1">机器学习策略 <a class="header-anchor" href="#机器学习策略" aria-label="Permalink to &quot;机器学习策略&quot;">​</a></h2><p><img src="https://pic3.zhimg.com/80/v2-f8252582639800e30e15a7a731d68bca_1440w.webp" alt=""></p><p>由此我们可以看出，机器学习是让机器能够解决上述应用问题的解决方案。也是在漫长的发展和尝试中，我们得出几种相对靠谱的学习方式：</p><ul><li>监督学习：对着课本进行教学</li><li>无监督学习：自学和自由阅读</li><li>强化学习：对学习成果予以奖励（和惩罚）</li><li>深度学习：大量的数据和神经网络的使用</li></ul><p>各种学习方式并不是冲突的，只是对输入、输出和中间态的处理方式不同，演化到今天，大多数的机器学习都会叠加多种学习方式以实现更好的训练效果。如，使用标记好的数据作为输入，基于深度神经网络进行学习。</p><h2 id="深度学习" tabindex="-1">深度学习 <a class="header-anchor" href="#深度学习" aria-label="Permalink to &quot;深度学习&quot;">​</a></h2><p><img src="https://pic4.zhimg.com/80/v2-1f471d7c7331603b1a08649595519dab_1440w.webp" alt=""></p><p>当我们的视角聚焦到深度学习时，我们终于捕捉到了生成式 AI、大语言模型这些最近比较火的名词。因为计算能力（CPU/GPU）的发展，通过神经网络训练的模型效果已经远远比其他学习方式来的强（所谓大力出奇迹）。</p><ul><li>当训练数据、参数到达一定的数量级后，就形成了“大”模型</li><li>根据数据类型（输入输出）分为语言模型和图像模型（可以扩展为语音、视频模型）</li><li>区别于判别型 AI（这个图片是不是一只小狗），生成式 AI 可以根据训练数据输出新的内容</li></ul><h2 id="llm-大语言模型" tabindex="-1">LLM 大语言模型 <a class="header-anchor" href="#llm-大语言模型" aria-label="Permalink to &quot;LLM 大语言模型&quot;">​</a></h2><p><img src="https://pic4.zhimg.com/80/v2-772a3863c18267c3706c9d70d3bf4c37_1440w.webp" alt=""></p><p>大语言模型和生成式 AI 的划分维度是不一样的，一个是以输入数据的量级来看，另一个则是输出内容的模式。但应用了大语言模型的训练方式之后，生成式 AI 的能力得到了巨大的提升，由此诞生出了我们最近所看到的 ChatGPT、LLaMA 等模型。所以在现阶段，我们也常常说 LLM = GenAI。</p><p>LLM 的训练方式，还是逃不出监督、无监督、强化学习和神经网络。之前的科技发展不断叠加，才使得 LLM 在 2022/2023 爆炸式的成功。</p><p>(参照：<a href="https://link.zhihu.com/?target=https%3A//www.bilibili.com/video/BV1ts4y1T7UH/" target="_blank" rel="noreferrer">【精校版】Andrej Karpathy微软Build大会精彩演讲： GPT状态和原理 - 解密OpenAI模型训练_哔哩哔哩_bilibili</a>）</p><p><img src="https://pic4.zhimg.com/80/v2-5d82f5e805af422ee8538b10a89517c3_1440w.webp" alt=""></p><p>LLM 的使用模式也因为 GenAI 的特性，和之前 is A==A 的模式有很大区别。我们可以用自然语言要求 AI “续写” 我们的任务 —— 即继续生成我们想要的但未给出的部分文字（或图像）。</p><p>因此我们也有了无需改变模型进行微调的方法，给出指向性前提和足够的 context 作为 prompt，即可影响 AI 的输出结果。</p><p>在图像模型上，还有 LoRA 技术可以在已有基础模型上进行叠加（比如，StableDiffusion），以调整模型的输出。</p><h2 id="神经网络" tabindex="-1">神经网络 <a class="header-anchor" href="#神经网络" aria-label="Permalink to &quot;神经网络&quot;">​</a></h2><p><img src="https://pic2.zhimg.com/80/v2-b556b86a0c89af9c1f11d72728b279a1_1440w.webp" alt=""></p><p>深度学习的核心 —— 神经网络的基本模型其实非常简单，多层感知机和全连接模型也是上个世纪就提出的概念。但数据量上去之后，神经元的连接也是指数级的增加，需要非常多优化和调整才能由计算机进行处理。</p><p><img src="https://pic4.zhimg.com/80/v2-b21431380163ff222a1726b727abea4f_1440w.webp" alt=""></p><p>DNN —— 想要表达更复杂的输入输出关系，要么增加参数、要么增加层数，“深度” 也就是这么来的，即增加神经网络的中间层数，来增加映射的多变性。</p><p>CNN —— 实际的神经元连接（推理计算）是邻接结构，即当前节点的值会受所有其他节点的影响，但这样的关系是无法被计算的。因此我们需要对节点关系进行采样滤波，只保留相关性更高的连接。</p><p>RNN —— 使上一次的输出状态参与计算，以便更好的处理一段文字、一段视频这种具有序列/时间相关的数据。</p>',34)])])}const m=i(p,[["render",r]]);export{b as __pageData,m as default};
